INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Beschaffungsprozess?', 2, '[{"text": "Systematische Anschaffung von Ressourcen", "correct": true, "because": "Planung und Umsetzung"}, {"text": "Softwareentwicklung", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Beschaffungsprozess?', 3, '[{"text": "Bedarfsgerechte Versorgung mit IT-Ressourcen", "correct": true, "because": "Optimale Ausstattung"}, {"text": "Systemleistung steigern", "correct": false, "because": "Indirekt"}, {"text": "Marketing verbessern", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum Beschaffungsprozess?', 5, '[{"text": "Bedarfsermittlung", "correct": true, "because": "Anforderungen definieren"}, {"text": "Angebotsvergleich", "correct": true, "because": "Kosten und Qualität prüfen"}, {"text": "Büroverschönerung", "correct": false, "because": "Kein Beschaffungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Beschaffungsprozess beginnt mit der Bedarfsanalyse. b) Er ist nur für Hardware relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Software und Dienstleistungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich im Beschaffungsprozess?', 4, '[{"text": "Budgetplanung", "correct": false, "because": "Kosten entscheidend"}, {"text": "Lieferantenauswahl", "correct": false, "because": "Qualität und Zuverlässigkeit"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Beschaffungsprozess eine Bedarfsanalyse enthält?', 2, '[{"text": "Ja", "correct": true, "because": "Erster Schritt"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Beschaffungsprozess für einen Fachinformatiker?', 3, '[{"text": "Sicherstellung der IT-Ausstattung", "correct": true, "because": "Ressourcen bereitstellen"}, {"text": "Softwareentwicklung", "correct": false, "because": "Anderer Bereich"}, {"text": "Marketing", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zum Beschaffungsprozess?', 5, '[{"text": "Anforderungsdefinition", "correct": true, "because": "Bedarf klären"}, {"text": "Bestellung", "correct": true, "because": "Umsetzung"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Beschaffungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Beschaffungsprozess optimiert die Ressourcennutzung. b) Er ist nur für große Firmen relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Beschaffungsprozess unwichtig?', 4, '[{"text": "Kostenanalyse", "correct": false, "because": "Budget entscheidend"}, {"text": "Lieferzeiten", "correct": false, "because": "Zeitplan wichtig"}, {"text": "Farbe der Büromöbel", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss der Beschaffungsprozess dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Nein", "correct": false, "because": "Empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein strukturierter Beschaffungsprozess?', 4, '[{"text": "Kosteneffizienz", "correct": true, "because": "Optimale Auswahl"}, {"text": "Zeitersparnis", "correct": true, "because": "Effiziente Planung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Beschaffungsprozess nur für Hardware gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software und Dienstleistungen"}, {"text": "Ja", "correct": false, "because": "Breiter anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im Beschaffungsprozess?', 3, '[{"text": "Bedarfserfüllung", "correct": true, "because": "Hauptziel"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Beschaffungsprozess umfasst Lieferantenauswahl. b) Er ist nur für neue Systeme nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Ersatzteile"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein unstrukturierter Beschaffungsprozess?', 5, '[{"text": "Höhere Kosten", "correct": true, "because": "Fehlende Vergleiche"}, {"text": "Verzögerungen", "correct": true, "because": "Unklare Planung"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker im Beschaffungsprozess?', 3, '[{"text": "Bedarf analysieren", "correct": true, "because": "Anforderungen ermitteln"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Beschaffungsprozess automatisiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. ERP-Systeme"}, {"text": "Nein", "correct": false, "because": "Automatisierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für den Beschaffungsprozess nutzen?', 4, '[{"text": "SAP", "correct": true, "because": "ERP für Beschaffung"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
